package com.foodordering.notification; import java.time.LocalDateTime; import java.util.*; import org.springframework.web.bind.annotation.*; record NotificationResponse(Long id,Long orderId,Long customerId,String message,LocalDateTime sentAt){} @RestController class NotificationController {private final NotificationRepository r;NotificationController(NotificationRepository r){this.r=r;}@GetMapping("/notifications") List<NotificationResponse> all(){return r.findAll().stream().map(n->new NotificationResponse(n.id,n.orderId,n.customerId,n.message,n.sentAt)).toList();}}
